const karaokeTestFitDock=document.createElement('section');
karaokeTestFitDock.id='karaokeTestFitDock';
karaokeTestFitDock.hidden=true;
karaokeTestFitDock.setAttribute('aria-label','Karaoke editable test fit');
document.querySelector('.right-panel').before(karaokeTestFitDock);

const karaokeFits=new Map();
const KARAOKE_TV_SIZES={55:{width:1218,height:685},75:{width:1660,height:934},80:{width:1771,height:996},100:{width:2214,height:1245}};
const fitClamp=(value,min,max)=>Math.max(min,Math.min(max,value));
const fitSnap=value=>Math.round(value/50)*50;
let activeKaraokeFitId=null,selectedFitItemId=null,fitDrag=null,fitItemCounter=0;

function karaokeRoomSize(zone){return{width:fitSnap(zone.w/PX_PER_METRE*1000),depth:fitSnap(zone.h/PX_PER_METRE*1000)}}
function fitItem(type,label,x,y,w,h,rotation=0){return{id:`kf${++fitItemCounter}`,type,label,x:fitSnap(x),y:fitSnap(y),w:fitSnap(w),h:fitSnap(h),rotation,flipped:false}}
function emptyKaraokeFit(zone){const{width,depth}=karaokeRoomSize(zone);return{zoneId:zone.id,width,depth,area:width*depth/1e6,items:[]}}
function autoKaraokeFit(zone){
 const {width,depth}=karaokeRoomSize(zone),area=width*depth/1e6,compact=area<12||Math.min(width,depth)<3200,sofaDepth=compact?750:850;
 const mainLength=fitSnap(fitClamp(width-1100,1800,2800)),sideLength=depth>=3300?fitSnap(fitClamp(depth-1900,1400,1800)):0;
 const tableW=fitSnap(fitClamp(width*.34,900,1400)),tableD=fitSnap(fitClamp(depth*.18,550,750)),tvSize=depth>=2000?80:55,tvSpec=KARAOKE_TV_SIZES[tvSize];
 const tv=fitItem('tv',`${tvSize}\" TV`,width-75-tvSpec.width/2,depth/2-25,tvSpec.width,50,90);tv.tvSize=tvSize;tv.w=tvSpec.width;tv.h=50;
 const items=[tv,fitItem('sofa','3 seater',50,depth-sofaDepth-50,mainLength,sofaDepth),fitItem('table','Coffee table',(width-tableW)/2,(depth-tableD)/2,tableW,tableD)];
 if(sideLength)items.push(fitItem('sofa','2 seater',50,Math.max(950,depth-sideLength-950),sofaDepth,sideLength));
 const fit={zoneId:zone.id,width,depth,area,items};keepFitItemInside(tv,fit);snapTvToWall(tv,fit);return fit;
}
function activeKaraokeFit(){return karaokeFits.get(activeKaraokeFitId)}
function fitColor(type){return type==='sofa'?'#c4c4c4':type==='table'?'#e5e5e5':'#212121'}
function fitTextColor(type){return type==='tv'?'#f7f8f5':'#212121'}
function fitSeats(item){return item.type==='sofa'?Math.max(1,Math.floor(Math.max(item.w,item.h)/700)):0}
function fitCapacity(fit){return fit.items.reduce((sum,item)=>sum+fitSeats(item),0)}
function fitFurnitureSymbol(item){
 const x=item.x,y=item.y,w=item.w,h=item.h,cx=x+w/2,cy=y+h/2;
 if(item.type==='sofa'){
  const seats=fitSeats(item),outer=Math.max(20,Math.min(55,h*.07)),arm=Math.max(70,Math.min(150,w*.075)),back=Math.max(85,Math.min(170,h*.2)),seatX=x+arm,seatY=y+back*.72,seatW=Math.max(1,w-arm*2),seatH=Math.max(1,h-back*.72-outer*.45),dividers=Array.from({length:Math.max(0,seats-1)},(_,index)=>{const dx=seatX+seatW*(index+1)/seats;return `<path class="fit-detail" d="M${dx} ${seatY+20}V${seatY+seatH-20}"/>`}).join('');
  return `<rect class="fit-block fit-sofa-base" x="${x}" y="${y}" width="${w}" height="${h}" rx="${outer}" fill="${fitColor(item.type)}"/><rect class="fit-detail-fill" x="${x+outer*.35}" y="${y+outer*.25}" width="${w-outer*.7}" height="${back}" rx="${outer*.65}"/><rect class="fit-detail-fill" x="${x+outer*.25}" y="${y+back*.48}" width="${arm}" height="${h-back*.48-outer*.25}" rx="${outer*.55}"/><rect class="fit-detail-fill" x="${x+w-arm-outer*.25}" y="${y+back*.48}" width="${arm}" height="${h-back*.48-outer*.25}" rx="${outer*.55}"/><rect class="fit-seat-fill" x="${seatX}" y="${seatY}" width="${seatW}" height="${seatH}" rx="${outer*.45}"/>${dividers}`;
 }
 if(item.type==='table'){const inset=Math.max(45,Math.min(100,Math.min(w,h)*.12));return `<rect class="fit-block fit-table-base" x="${x}" y="${y}" width="${w}" height="${h}" rx="45" fill="${fitColor(item.type)}"/><rect class="fit-table-inset" x="${x+inset}" y="${y+inset}" width="${Math.max(1,w-inset*2)}" height="${Math.max(1,h-inset*2)}" rx="28"/>`}
 return `<rect class="fit-block" x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${fitColor(item.type)}"/>`;
}
function fitLibraryIcon(type){
 if(type==='sofa')return `<svg viewBox="0 0 64 42" aria-hidden="true"><rect x="7" y="8" width="50" height="27" rx="5"/><path d="M12 8v27M52 8v27M12 16h40M32 16v19"/></svg>`;
 if(type==='table')return `<svg viewBox="0 0 64 42" aria-hidden="true"><rect x="8" y="8" width="48" height="26" rx="3"/><rect x="13" y="13" width="38" height="16" rx="2"/></svg>`;
 if(type==='tv')return `<svg viewBox="0 0 64 42" aria-hidden="true"><rect x="8" y="8" width="48" height="25" rx="2"/><path d="M25 37h14M32 33v4"/></svg>`;
 return `<svg viewBox="0 0 64 42" aria-hidden="true"><path d="M15 22a17 17 0 1 0 5-12M15 8v14h14"/></svg>`;
}
function fitLibrary(){return `<div class="test-fit-library" aria-label="Add furniture"><button data-fit-add="sofa">${fitLibraryIcon('sofa')}<span>Sofa</span></button><button data-fit-add="table">${fitLibraryIcon('table')}<span>Table</span></button><button data-fit-add="tv">${fitLibraryIcon('tv')}<span>TV / AV</span></button><button data-fit-action="reset">${fitLibraryIcon('reset')}<span>Auto fit</span></button></div>`}
function liveDoorForZone(zone,fit){
 let best=null;
 for(const door of state.doors||[]){
  const edge=typeof doorEdge==='function'?doorEdge(door):null;if(!edge)continue;
  const angle=edge.angle*Math.PI/180,end={x:edge.x+Math.cos(angle)*edge.width,y:edge.y+Math.sin(angle)*edge.width},mid={x:(edge.x+end.x)/2,y:(edge.y+end.y)/2};
  const sides=[['left',Math.abs(mid.x-zone.x)],['right',Math.abs(mid.x-(zone.x+zone.w))],['top',Math.abs(mid.y-zone.y)],['bottom',Math.abs(mid.y-(zone.y+zone.h))]],nearest=sides.sort((a,b)=>a[1]-b[1])[0];
  const within=nearest[0]==='left'||nearest[0]==='right'?mid.y>=zone.y-8&&mid.y<=zone.y+zone.h+8:mid.x>=zone.x-8&&mid.x<=zone.x+zone.w+8;
  if(!within||nearest[1]>12||best&&best.distance<=nearest[1])continue;
  const scale=1000/PX_PER_METRE,start={x:(edge.x-zone.x)*scale,y:(edge.y-zone.y)*scale},finish={x:(end.x-zone.x)*scale,y:(end.y-zone.y)*scale};
  const hinge=door.flipX?finish:start,jamb=door.flipX?start:finish,normal={x:-Math.sin(angle)*(door.flipY?-1:1),y:Math.cos(angle)*(door.flipY?-1:1)},leaf={x:hinge.x+normal.x*door.widthMm,y:hinge.y+normal.y*door.widthMm};
  best={id:door.id,side:nearest[0],width:door.widthMm,hinge,jamb,leaf,distance:nearest[1]};
 }
 return best;
}
function fitDoorSvg(door){if(!door)return '';const{hinge:h,jamb:j,leaf:l,width}=door,cross=(j.x-h.x)*(l.y-h.y)-(j.y-h.y)*(l.x-h.x),sweep=cross>0?1:0;return `<g class="test-fit-live-door"><path d="M${h.x} ${h.y}L${j.x} ${j.y}" stroke="#f7f8f5" stroke-width="112"/><path d="M${h.x} ${h.y}L${l.x} ${l.y}" stroke="#7c7c7c" stroke-width="24"/><path d="M${j.x} ${j.y}A${width} ${width} 0 0 ${sweep} ${l.x} ${l.y}" fill="none" stroke="#7c7c7c" stroke-width="18"/><circle cx="${h.x}" cy="${h.y}" r="35" fill="#212121"/><text x="${(h.x+j.x)/2}" y="${(h.y+j.y)/2-75}" text-anchor="middle" fill="#707070" font-size="65">${width} mm</text></g>`}
function fitBlock(item){const cx=item.x+item.w/2,cy=item.y+item.h/2,flip=item.flipped?`translate(0 ${cy*2}) scale(1 -1)`:'';return `<g class="test-fit-item ${item.id===selectedFitItemId?'selected':''}" data-fit-item="${item.id}" transform="rotate(${item.rotation} ${cx} ${cy})"><g transform="${flip}">${fitFurnitureSymbol(item)}</g></g>`}
function testFitSvg(fit){const w=fit.width,d=fit.depth,zone=state.zones.find(item=>item.id===fit.zoneId),door=zone?liveDoorForZone(zone,fit):null;return `<svg id="karaokeTestFitSvg" viewBox="-260 -260 ${w+520} ${d+520}" role="img" aria-label="Editable Karaoke test fit with 100 millimetre walls and live plan door"><defs><pattern id="fitGrid" width="500" height="500" patternUnits="userSpaceOnUse"><path d="M500 0H0V500" fill="none" stroke="#e5e5e5" stroke-width="8"/></pattern></defs><rect width="${w}" height="${d}" fill="#f7f8f5"/><rect width="${w}" height="${d}" fill="url(#fitGrid)"/><rect x="0" y="0" width="${w}" height="${d}" fill="none" stroke="#555555" stroke-width="100"/>${fitDoorSvg(door)}${fit.items.map(fitBlock).join('')}<path d="M0 -105H${w}M0 -155V-55M${w} -155V-55" stroke="#7c7c7c" stroke-width="13"/><text x="${w/2}" y="-145" text-anchor="middle" fill="#212121" font-size="90" font-weight="700">${w.toLocaleString()} mm</text><path d="M-105 0V${d}M-155 0H-55M-155 ${d}H-55" stroke="#7c7c7c" stroke-width="13"/><text x="-145" y="${d/2}" transform="rotate(-90 -145 ${d/2})" text-anchor="middle" fill="#212121" font-size="90" font-weight="700">${d.toLocaleString()} mm</text><text x="${w-40}" y="${d-45}" text-anchor="end" fill="#707070" font-size="58">WALL · 100 mm</text></svg>`}
function fitInspector(fit){const item=fit.items.find(entry=>entry.id===selectedFitItemId);if(!item)return `<div class="test-fit-inspector test-fit-empty"><span>Select an item to edit its size</span></div>`;return `<div class="test-fit-inspector"><div class="test-fit-selected"><span>${esc(item.label)}</span><button data-fit-action="rotate" title="Rotate 90° (R)" aria-label="Rotate 90 degrees">↻</button><button class="fit-delete" data-fit-action="delete" title="Delete" aria-label="Delete">×</button></div><div class="test-fit-dimensions"><label>Width <span>mm</span><input data-fit-field="w" type="number" min="150" step="50" value="${item.w}" inputmode="numeric"></label><span class="test-fit-times">×</span><label>Depth <span>mm</span><input data-fit-field="h" type="number" min="50" step="50" value="${item.h}" inputmode="numeric"></label></div><p class="test-fit-shortcuts"><kbd>R</kbd> Rotate <kbd>F</kbd> Flip</p></div>`}
function renderKaraokeTestFit(){const fit=activeKaraokeFit();if(!fit)return;karaokeTestFitDock.innerHTML=`<header class="test-fit-head"><div><small>EDITABLE PARAMETRIC TEST FIT · CONCEPT ONLY</small><strong>Karaoke Test Fit</strong><span>${fit.width.toLocaleString()} × ${fit.depth.toLocaleString()} mm · ${fit.area.toFixed(2)} m² · 100 mm walls</span></div><button data-fit-action="reset" title="Reset auto layout" aria-label="Reset auto layout">↺</button><button data-fit-action="close" aria-label="Close Test Fit">×</button></header><div class="test-fit-body"><div class="test-fit-canvas">${testFitSvg(fit)}</div><aside class="test-fit-tools">${fitLibrary()}${fitInspector(fit)}</aside></div>`}
function openKaraokeAnalysis(id){const zone=state.zones.find(item=>item.id===id);if(!zone||ideaRoomKey(zone.name)!=='karaoke')return toast('Select the Karaoke room first');activeKaraokeFitId=id;const size=karaokeRoomSize(zone),stored=karaokeFits.get(id);if(!stored||stored.width!==size.width||stored.depth!==size.depth)karaokeFits.set(id,emptyKaraokeFit(zone));selectedFitItemId=karaokeFits.get(id).items[0]?.id||null;$('#ideaRail').hidden=true;$('.workspace').classList.remove('ideas-open');$('.workspace').classList.add('test-fit-open');karaokeTestFitDock.hidden=false;renderKaraokeTestFit()}
function syncKaraokeTestFit(){if(karaokeTestFitDock.hidden||!activeKaraokeFitId)return;const zone=state.zones.find(item=>item.id===activeKaraokeFitId);if(!zone||ideaRoomKey(zone.name)!=='karaoke'){karaokeTestFitDock.hidden=true;$('.workspace').classList.remove('test-fit-open');return}const size=karaokeRoomSize(zone),fit=activeKaraokeFit();if(!fit||fit.width!==size.width||fit.depth!==size.depth){karaokeFits.set(zone.id,emptyKaraokeFit(zone));selectedFitItemId=null;renderKaraokeTestFit();toast('Karaoke Test Fit cleared for the resized room')}}
function syncKaraokeTestFitDoor(){if(!karaokeTestFitDock.hidden&&activeKaraokeFitId)renderKaraokeTestFit()}
function fitPoint(event){const svg=karaokeTestFitDock.querySelector('#karaokeTestFitSvg'),point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;return point.matrixTransform(svg.getScreenCTM().inverse())}
function fitItemBounds(item){const quarter=Math.abs(Math.round(item.rotation/90))%2,cx=item.x+item.w/2,cy=item.y+item.h/2,bw=quarter?item.h:item.w,bh=quarter?item.w:item.h;return{cx,cy,bw,bh,left:cx-bw/2,right:cx+bw/2,top:cy-bh/2,bottom:cy+bh/2}}
function keepFitItemInside(item,fit){const inset=50,bounds=fitItemBounds(item),minX=inset+bounds.bw/2,maxX=fit.width-inset-bounds.bw/2,minY=inset+bounds.bh/2,maxY=fit.depth-inset-bounds.bh/2,cx=minX<=maxX?fitClamp(bounds.cx,minX,maxX):fit.width/2,cy=minY<=maxY?fitClamp(bounds.cy,minY,maxY):fit.depth/2;item.x=fitSnap(cx-item.w/2);item.y=fitSnap(cy-item.h/2)}
function snapTvToWall(item,fit,threshold=300){if(item.type!=='tv')return;let bounds=fitItemBounds(item),nearest=[['left',Math.abs(bounds.left-50)],['right',Math.abs(bounds.right-(fit.width-50))],['top',Math.abs(bounds.top-50)],['bottom',Math.abs(bounds.bottom-(fit.depth-50))]].sort((a,b)=>a[1]-b[1])[0];if(nearest[1]>threshold)return;const side=nearest[0];item.rotation=side==='left'||side==='right'?90:0;keepFitItemInside(item,fit);bounds=fitItemBounds(item);if(side==='left')item.x+=50-bounds.left;if(side==='right')item.x+=fit.width-50-bounds.right;if(side==='top')item.y+=50-bounds.top;if(side==='bottom')item.y+=fit.depth-50-bounds.bottom}
karaokeTestFitDock.addEventListener('pointerdown',event=>{const group=event.target.closest('[data-fit-item]');if(!group)return;const fit=activeKaraokeFit(),item=fit.items.find(entry=>entry.id===group.dataset.fitItem);if(!item)return;selectedFitItemId=item.id;const point=fitPoint(event);fitDrag={id:item.id,dx:point.x-item.x,dy:point.y-item.y,pointerId:event.pointerId};renderKaraokeTestFit();karaokeTestFitDock.setPointerCapture?.(event.pointerId);event.preventDefault()});
karaokeTestFitDock.addEventListener('pointermove',event=>{if(!fitDrag||event.pointerId!==fitDrag.pointerId)return;const fit=activeKaraokeFit(),item=fit.items.find(entry=>entry.id===fitDrag.id),point=fitPoint(event);item.x=point.x-fitDrag.dx;item.y=point.y-fitDrag.dy;keepFitItemInside(item,fit);snapTvToWall(item,fit);renderKaraokeTestFit()});
karaokeTestFitDock.addEventListener('pointerup',event=>{if(fitDrag&&event.pointerId===fitDrag.pointerId)fitDrag=null});
karaokeTestFitDock.addEventListener('change',event=>{const field=event.target.dataset.fitField;if(!field)return;const fit=activeKaraokeFit(),item=fit.items.find(entry=>entry.id===selectedFitItemId);if(!item)return;if(field==='dimensions'){const values=event.target.value.match(/\d+(?:\.\d+)?/g)?.map(Number);if(!values||values.length<2){event.target.value=`${item.w} × ${item.h}`;return}item.w=Math.max(150,fitSnap(values[0]));item.h=Math.max(50,fitSnap(values[1]));if(item.type==='tv')item.tvSize=null}else if(field==='label')item.label=event.target.value.trim()||item.label;else if(field==='tvSize'){item.tvSize=Number(event.target.value);const spec=KARAOKE_TV_SIZES[item.tvSize];item.label=`${item.tvSize}\" TV`;item.w=spec.width;item.h=50}else item[field]=field==='rotation'?Number(event.target.value)||0:fitSnap(Number(event.target.value)||0);if((field==='w'||field==='h')&&item.type!=='tv')item[field]=Math.max(150,item[field]);keepFitItemInside(item,fit);snapTvToWall(item,fit);renderKaraokeTestFit()});
karaokeTestFitDock.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const fit=activeKaraokeFit(),action=button.dataset.fitAction,add=button.dataset.fitAdd;if(action==='close'){karaokeTestFitDock.hidden=true;$('.workspace').classList.remove('test-fit-open');fitDrag=null;return}if(action==='reset'){const zone=state.zones.find(item=>item.id===activeKaraokeFitId);karaokeFits.set(zone.id,autoKaraokeFit(zone));selectedFitItemId=karaokeFits.get(zone.id).items[0]?.id||null;renderKaraokeTestFit();return}if(add){const defaults=add==='sofa'?['Sofa',1800,800]:add==='table'?['Table',1000,600]:['75\" TV',KARAOKE_TV_SIZES[75].width,50],item=fitItem(add,defaults[0],(fit.width-defaults[1])/2,(fit.depth-defaults[2])/2,defaults[1],defaults[2]);if(add==='tv'){item.tvSize=75;item.w=KARAOKE_TV_SIZES[75].width;item.h=50}fit.items.push(item);keepFitItemInside(item,fit);snapTvToWall(item,fit);selectedFitItemId=item.id;renderKaraokeTestFit();return}const item=fit.items.find(entry=>entry.id===selectedFitItemId);if(!item)return;if(action==='rotate'){item.rotation=(item.rotation+90)%360;keepFitItemInside(item,fit);snapTvToWall(item,fit);renderKaraokeTestFit()}if(action==='delete'){fit.items=fit.items.filter(entry=>entry.id!==item.id);selectedFitItemId=fit.items[0]?.id||null;renderKaraokeTestFit()}});
document.addEventListener('keydown',event=>{if(karaokeTestFitDock.hidden||event.metaKey||event.ctrlKey||event.altKey)return;const target=event.target;if(target.matches?.('input,select,textarea')||target.isContentEditable)return;const key=event.key.toLowerCase();if(key!=='r'&&key!=='f')return;const fit=activeKaraokeFit(),item=fit?.items.find(entry=>entry.id===selectedFitItemId);if(!item)return;event.preventDefault();if(key==='r'){item.rotation=(item.rotation+90)%360;keepFitItemInside(item,fit);snapTvToWall(item,fit)}else item.flipped=!item.flipped;renderKaraokeTestFit()});
